script:
'use strict';
const BASE = String(triomi.baseUrl || 'https://18comic.vip').replace(/\/+$/, '');
const API = 'https://www.cdnhjk.net';
const COVER = 'https://cdn-msp.' + BASE.replace(/^https:\/\//, '');
function fail(message) { throw new Error('JMComic：' + message); }
function validId(value) { value = String(value == null ? '' : value); if (!/^[1-9][0-9]*$/.test(value)) fail('作品/章节标识无效'); return value; }
function pageNumber(page) { if (!Number.isInteger(page) || page < 1) fail('页码无效'); return page; }
async function api(path) {
  const response = await triomi.fetch(API + path);
  if (response.status !== 200) fail('API HTTP ' + response.status);
  let envelope;
  try { envelope = JSON.parse(response.body); } catch (_) { fail('API 返回无效 JSON'); }
  if (!envelope || envelope.code !== 200 || envelope.data == null) fail('API 内容不可用');
  return envelope.data;
}
async function text(value) {
  // Decode entities as text without interpreting a title as downloaded markup.
  return await triomi.value('<p>' + String(value || '').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</p>', 'p', 'text') || '';
}
async function listItem(album) {
  if (!album || typeof album.name !== 'string' || !album.name.trim()) fail('列表作品标题缺失');
  const id = validId(album.id);
  return {remoteId: id, title: await text(album.name), type: 'manga', url: BASE + '/album/' + id + '/',
    coverUrl: COVER + '/media/albums/' + id + '_3x4.jpg',
    author: typeof album.author === 'string' ? album.author : '',
    tags: [album.category && album.category.title, album.category_sub && album.category_sub.title].filter(Boolean)};
}
async function items(data) {
  if (!data || !Array.isArray(data.content)) fail('列表格式无效');
  if (data.content.length > 1000) fail('列表超过安全限制');
  const result = [];
  for (const album of data.content) result.push(await listItem(album));
  return result;
}
async function discover(url, page) {
  pageNumber(page);
  const match = /[?&]o=(mv(?:_w|_m|_t)?|mr)$/.exec(url);
  return items(await api('/categories/filter?page=' + page + '&c=0&o=' + (match ? match[1] : 'mv')));
}
async function album(id) {
  const value = await api('/album?id=' + validId(id));
  if (!value || Array.isArray(value) || typeof value !== 'object') return null;
  validId(value.id);
  if (String(value.id) !== String(id)) fail('API 作品身份不匹配');
  return value;
}
async function canonicalAlbum(id) {
  let value = await album(id);
  if (!value) return null;
  if (String(value.series_id || '0') !== '0' && String(value.series_id) !== String(id)) {
    const parent = validId(value.series_id);
    value = await album(parent);
    if (value && String(value.id) !== parent) fail('合集身份不匹配');
  }
  return value;
}
async function fullItem(value) {
  const result = await listItem(Object.assign({}, value, {author: (value.author || []).join(' / ')}));
  const tags = Array.isArray(value.tags) ? value.tags : [];
  result.tags = tags.filter(t => ['连载中', '连载', '完结'].indexOf(t) < 0);
  result.status = tags.some(t => t === '连载中' || t === '连载') ? '连载中' : (tags.indexOf('完结') >= 0 ? '已完结' : '未知');
  result.description = await text(value.description || '');
  for (const pair of [['作品', value.works], ['登场人物', value.actors]]) {
    if (Array.isArray(pair[1]) && pair[1].length) result.description += '\n\n' + pair[0] + '：' + pair[1].join('、');
  }
  return result;
}
async function search(keyword, page) { return searchTagged(keyword, page, []); }
async function searchTags() {
  const data = await api('/categories');
  if (!data || !Array.isArray(data.categories)) fail('分类数据无效');
  const result = [];
  for (const group of data.categories) {
    const slug = String(group.slug || '0');
    if (!/^[a-zA-Z0-9_-]+$/.test(slug) || typeof group.name !== 'string') fail('分类标识无效');
    result.push({id: 'category:' + slug, label: group.name});
    for (const sub of group.sub_categories || []) {
      if (!/^[a-zA-Z0-9_-]+$/.test(sub.slug) || typeof sub.name !== 'string') fail('子分类标识无效');
      result.push({id: 'category:' + slug + '_' + sub.slug, label: group.name + ' · ' + sub.name});
    }
  }
  for (const block of data.blocks || []) {
    for (const tag of block.content || []) if (typeof tag === 'string' && tag.trim()) result.push({id: 'tag:' + tag, label: tag});
  }
  return result;
}
async function searchTagged(keyword, page, tags) {
  pageNumber(page);
  const query = String(keyword || '').trim(), id = /^(?:JM\s*:?\s*)?([1-9][0-9]*)$/i.exec(query);
  if (id && !(tags && tags.length)) {
    if (page !== 1) return [];
    const value = await canonicalAlbum(id[1]);
    return value ? [await fullItem(value)] : [];
  }
  const categories = [], terms = query ? [query] : [];
  for (const tag of tags || []) {
    const category = /^category:([a-zA-Z0-9_-]+)$/.exec(tag), term = /^tag:(.+)$/.exec(tag);
    if (category) categories.push(category[1]); else if (term) terms.push(term[1]); else fail('筛选项无效');
  }
  if (categories.length > 1 || categories.length && terms.length) fail('源站分类不能与关键词/标签组合');
  if (!terms.length) return items(await api('/categories/filter?page=' + page + '&c=' + (categories[0] || '0') + '&o=mv'));
  const data = await api('/search?search_query=' + encodeURIComponent(terms.join(' +')) + '&o=mv&search_type=0&page=' + page);
  if (data && data.redirect_aid != null) {
    if (page !== 1) return [];
    const value = await canonicalAlbum(validId(data.redirect_aid));
    return value ? [await fullItem(value)] : [];
  }
  return items(data);
}
async function detail(url, snapshot) {
  const match = /\/(?:album|photo)\/([1-9][0-9]*)\/?$/.exec(url || '');
  const id = match ? match[1] : validId(snapshot.remoteId);
  const value = await canonicalAlbum(id);
  if (!value) fail('作品不存在或已下架');
  const item = await fullItem(value), series = value.series || [];
  if (!Array.isArray(series) || series.length > 5000) fail('章节目录无效或过大');
  const seen = new Set();
  const chapters = series.map((ep, index) => {
    const cid = validId(ep.id), order = Number(ep.sort);
    if (seen.has(cid) || !Number.isFinite(order) || order < 0) fail('章节顺序或标识无效');
    seen.add(cid);
    const prefix = '第' + ep.sort + '话', title = String(ep.name || '');
    return {remoteId: cid, title: title.startsWith('第') ? title : prefix + (title ? ' ' + title : ''),
      url: BASE + '/photo/' + cid, number: order, sortIndex: order};
  }).sort((a, b) => a.sortIndex - b.sortIndex);
  if (!chapters.length) chapters.push({remoteId: String(value.id), title: '单章节',
    url: BASE + '/photo/' + value.id + '/', sortIndex: 0});
  return {item: item, chapters: chapters};
}
async function content(url, chapter) {
  const match = /\/photo\/([1-9][0-9]*)\/?$/.exec(url || '');
  const id = match ? match[1] : validId(chapter.remoteId);
  const data = await api('/comic_read?id=' + id + '&express=');
  if (!data || !Array.isArray(data.images) || !data.images.length || data.images.length > 5000) fail('章节不存在或图片列表为空');
  const seen = new Set();
  const images = data.images.map(row => {
    if (!row || typeof row.image !== 'string' || !/^https:\/\/[^\s"'<>\\@]+\/media\/photos\/[1-9][0-9]*\/[^/?#]+\.[a-z0-9]+(?:\?[^\s"'<>\\]*)?$/i.test(row.image)) fail('图片地址格式无效或不是 HTTPS');
    const aid = /\/media\/photos\/([0-9]+)\//.exec(row.image)[1];
    if (aid !== id || seen.has(row.image)) fail('图片章节身份不匹配或存在重复页');
    seen.add(row.image); return row.image;
  });
  return {images: images, imageHeaders: {'Referer': BASE + '/', 'User-Agent': 'Mozilla/5.0'}};
}
